import pandas as pd, numpy as np
import statsmodels.formula.api as smf
from sklearn.model_selection import KFold
df=pd.read_csv('data.csv')
models={
 'spline_base': 'dY ~ bs(D, df=8, degree=3) + log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier)',
 'spline_placebo': 'dY ~ bs(D, df=8, degree=3) + dY_placebo + log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier)',
 'spline_placebo_sq': 'dY ~ bs(D, df=8, degree=3) + dY_placebo + log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier) + I(log_hist_days**2) + I(log_pre_gmv**2) + I(orders**2)',
 'linear_placebo_sq': 'dY ~ D + dY_placebo + log_hist_days + C(region) + log_pre_gmv + orders + cat_share + tenure + C(tier) + I(log_hist_days**2) + I(log_pre_gmv**2) + I(orders**2)',
}
kf=KFold(5, shuffle=True, random_state=42)
results={name:[] for name in models}
for tr,val in kf.split(df):
    train=df.iloc[tr]; test=df.iloc[val]
    for name,f in models.items():
        try:
            mod=smf.ols(f,data=train).fit()
            pred=mod.predict(test)
            rmse=np.sqrt(np.mean((test.dY-pred)**2))
            results[name].append(rmse)
        except Exception as e:
            results[name].append(np.nan)
for name in models:
    arr=np.array(results[name])
    print(name, 'CV RMSE', arr.mean(), arr)
